window.futvizVista("defensa","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"defensa\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"defensa\"]={\"id\":\"defensa\",\"titulo\":\"Goles recibidos vs. xG en contra\",\"bajada\":\"A la derecha, menos xG en contra; arriba, menos goles recibidos. Arriba a la derecha, los mejores.\",\"pregunta\":\"\u00bfQui\u00e9n defiende mejor y c\u00f3mo?\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"xg_con\",\"label\":\"xG en contra por partido (sin penales); menos, a la derecha\",\"corto\":\"xG en contra\",\"dec\":2,\"invertir\":true},\"y\":{\"col\":\"gol_con\",\"label\":\"Goles recibidos por partido (sin penales); menos, arriba\",\"corto\":\"Goles recibidos\",\"dec\":2,\"invertir\":true},\"referencia\":{\"tipo\":\"diagonal\",\"dif\":\"goles recibidos \u2212 xG en contra\",\"sobre\":\"Reciben menos de lo esperado\",\"bajo\":\"Reciben m\u00e1s de lo esperado\",\"decDif\":2},\"requiere\":[\"xg_con\",\"gol_con\"],\"subtitulo\":\"Equipos de las 5 ligas \u00b7 {temporada} \u00b7 por partido, sin penales\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"x\",\"etiqueta\":\"xG en contra\",\"ayuda\":\"Ordenados por xG en contra por partido (sin penales); menos, a la derecha: primero los que menos ocasiones conceden\"},{\"id\":\"y\",\"etiqueta\":\"Goles recibidos\",\"ayuda\":\"Ordenados por Goles recibidos por partido (sin penales); menos, arriba: primero los que menos goles reciben\"}],\"queMirar\":\"Los dos ejes van **al rev\u00e9s**: a la derecha, menos xG en contra; arriba, menos goles recibidos, as\u00ed que arriba a la derecha est\u00e1n los mejores. Ojo: el xG de Understat suma m\u00e1s de lo que entra, as\u00ed que la mayor\u00eda de los equipos queda sobre la diagonal: compara a cada equipo con los dem\u00e1s de su temporada, no con la l\u00ednea. La distancia a la diagonal junta portero, bloqueos y suerte, casi no se repite de un a\u00f1o a otro y no sirve para decir qui\u00e9n tiene al mejor portero.\",\"insight\":\"defensa\",\"fuente\":\"Understat\",\"colorPor\":[\"liga\"]};</script>");